INSERT INTO t_owner_account_no_sequence (id, entity_type, entity_id, currency, account_code, `last_value`, create_time, update_time)
VALUES (#{id}, #{entityType}, #{entityId}, #{currency}, #{accountCode}, LAST_INSERT_ID(1), #{createTime}, #{updateTime})
ON DUPLICATE KEY UPDATE `last_value` = LAST_INSERT_ID(`last_value` + 1), update_time = #{updateTime}
